def colorGrid(n, m, sources):
    # Flat grid: cell (r, c) is stored at index r * m + c; 0 means uncolored
    grid = [0] * (n * m)
    frontier = []
    for r, c, color in sources:
        grid[r * m + c] = color
        frontier.append(r * m + c)

    # Each loop iteration is one time step (one BFS level)
    while frontier:
        # offer[cell] = largest color offered to this uncolored cell during this step
        offer = {}
        for cell in frontier:
            r, c = divmod(cell, m)
            color = grid[cell]
            # Try to spread to the four neighbors
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if 0 <= nr < n and 0 <= nc < m:
                    nxt = nr * m + nc
                    # Only uncolored cells can be reached
                    if grid[nxt] == 0:
                        # On a tie in time, the larger color wins
                        if offer.get(nxt, 0) < color:
                            offer[nxt] = color
        # Apply all spreads at once; these cells are the next frontier
        frontier = []
        for cell, color in offer.items():
            grid[cell] = color
            frontier.append(cell)

    # Rebuild the 2D grid from the flat one
    return [grid[r * m:(r + 1) * m] for r in range(n)]
